def make_slides():
    slides=[]
    def add(title,body,image,sources,notes='',cue=''):
        slides.append(dict(title=title,body=body,image='methods/'+image+'.png',sources=sources,notes=notes,cue=cue))
    add('Tracking Data Applied',['Soccer analytics with SkillCorner','From coordinates to football questions','Methods, assumptions and interpretation'],'coordinates',['skillcorner'],'Introduce the match and the distinction between observed tracking, extrapolated tracking and derived labels.')
    add('Data and documentation',['SkillCorner/opendata: tracking and supplied labels','kloppy: load and standardize','DataBallPy: metric explanations and models'],'loading',['skillcorner','kloppy','distance'],'The opening entries are linked. Full sources are in the reading list. Real sample: Brisbane vs Perth, 21 December 2024, match 1925299.')
    add('Loading tracking data',['Load match metadata and JSONL with kloppy','Retain frame IDs, periods and native metres','Convert to a dataframe for analysis'],'loading',['kloppy'],'The figure contains actual dataframe values; velocity columns are derived after loading.',cue='NOTEBOOK · load and inspect')
    add('Tracking quality and visibility',['Separate detected from extrapolated positions','Keep missingness and coverage visible','Avoid derivatives across gaps or periods'],'quality',['skillcorner','preprocess'],'Red rings mark extrapolated players according to raw is_detected. Coordinates can exist without a direct camera observation. All subsequent models inherit this uncertainty.')
    add('Plotting a tracking frame',['Draw the pitch in the data’s coordinate system','Color by team and identify the ball','Check direction before calculating goal-related features'],'coordinates',['skillcorner'],'Use actual pitch dimensions. A visually plausible frame is a useful first check, but does not prove identity or position accuracy.')
    add('Animating a sequence',['Keep player identities consistent across frames','Use playback to inspect motion and tactical context','Overlay model outputs on the same sequence'],'animation',['kloppy','fot'],'Three snapshots are from the real selected clip. The notebook contains a full embedded animation.',cue='NOTEBOOK · play the sequence')
    add('Possession detection',['Find the nearest player inside a candidate zone','Use ball motion to distinguish touches from flyovers','Leave ambiguous frames unassigned'],'possession',['preprocess','pathcrf'],'Figure is an actual 2 m proximity heuristic, not the full Vidal-Codina or PathCRF method. Pros: transparent and quick. Cons: aerial balls, duels and tracking uncertainty. Compare with supplied possession labels; evaluate timing-aware accuracy.',cue='NOTEBOOK · inspect the candidate detector')
    add('Pass-event detection',['Detect release, ball travel and reception cues','Track a change between plausible player possessions','Validate event timing against video or labels'],'pass_detection',['pathcrf','preprocess'],'The real ball path is annotated at supplied possession endpoints. This is an explanatory candidate sequence, not a validated recovered pass. Pros: converts continuous signals to actionable events. Cons: missing ball data and multi-touch ambiguity.')
    add('Formation detection',['Remove team translation with centered coordinates','Separate in-possession and defensive samples','Estimate stable role locations over a window'],'formation',['formation'],'Real median outfield positions are shown separately by possession. Pros: summarizes organization beyond a team sheet. Cons: averaging mixes roles and game states; these are not asserted formation labels.')
    add('Player-role and line detection',['Group longitudinal positions into candidate lines','Assign roles consistently through player exchanges','Treat cluster count as a modeling choice'],'role_lines',['formation'],'Ward clustering of real centered x positions into three groups is a teaching baseline. It is not a validated named-formation classifier. Pros: interpretable. Cons: fixed line counts, overlaps and rotations.')
    add('Phase-of-play segmentation',['Represent phases as intervals rather than single events','Join intervals to tracking by period and frame','Compare structure and effort within tactical context'],'phases',['skillcorner','phases'],'The plot shows supplied SkillCorner labels, not predictions from a classifier trained here. Pros: makes context explicit. Cons: taxonomy-dependent and sensitive to boundary definitions.',cue='NOTEBOOK · join phase intervals')
    add('Estimating player speed',['Smooth positions within valid continuous segments','Differentiate coordinates using elapsed time','Convert m/s to km/h for running bands'],'speed',['preprocess'],'Actual speed curves are shown. Pros: foundation for physical and tactical features. Cons: derivatives amplify noise; smoothing removes some short peaks.')
    add('Distance covered',['Integrate speed across valid intervals','Distance ≈ Σ speed × Δt','Report coverage alongside the total'],'distance',['distance','physical'],'The real sample’s cumulative distance excludes missing derivatives. No full-match extrapolation. Pros: simple workload volume measure. Cons: incomplete and extrapolated tracking affect accuracy.')
    add('High-speed and sprint distance',['HSR: documented men’s band 20–25 km/h','Sprint: above 25 km/h','Accumulate distance separately in each band'],'zones',['physical','distance'],'Our code uses [20,25) and [25,infinity) to avoid overlap; exact equality handling is a teaching convention. Pros: distinguishes intensity from volume. Cons: thresholds and exposure affect comparisons.')
    add('Sprint-effort counts',['Group consecutive threshold-exceeding frames','Require a stated minimum duration','Define whether brief gaps are merged'],'efforts',['physical'],'Shaded segments are our >=1 s, no-merging teaching rule. They are not exact SkillCorner production sprint counts. Pros: repeated-effort view. Cons: sensitive to thresholds, smoothing and merging rules.')
    add('Acceleration and deceleration',['Differentiate scalar speed for speeding up or slowing down','Keep signed acceleration distinct from vector magnitude','Check duration as well as peak acceleration'],'acceleration',['preprocess','explosive'],'The plot uses real signed speed derivatives. A direction change can produce acceleration-vector magnitude without increasing scalar speed. Pros: captures bursts and braking. Cons: highly noise-sensitive; threshold crossing alone does not qualify a production explosive effort.')
    add('Time to high-speed running',['SkillCorner measures the 9 → 20 km/h interval','Use a qualifying explosive acceleration','Compare the speed trajectory, not just peak speed'],'time_hsr',['explosive'],'The real crossing is illustrative, not production-qualified. The published metric is the minimum interval within qualifying explosive accelerations. Start detection, >0.7 s high-acceleration qualification and filtering matter.')
    add('Time to sprint',['SkillCorner measures the 9 → 25 km/h interval','A quick top speed does not imply a quick acceleration','Check the qualifying effort before reporting the metric'],'time_sprint',['explosive'],'Real observed crossing shown. No official Time to Sprint or Top 3 value is reconstructed. Pros: explosiveness/capacity. Cons: limited opportunities, sample size and qualification rules.')
    add('PSV-99: activity-based speed capacity',['Use SkillCorner’s defined activity population','Summarize high-speed activity rather than all frames','Do not substitute an all-frame percentile'],'peak',['peak'],'The real frame-speed distribution illustrates why populations matter. SkillCorner describes PSV-99 over physical activities above 15 km/h. This histogram is not the official PSV-99 calculation.')
    add('Peak Velocity: absolute top speed',['Identify the highest reliably measured speed','Inspect the quality of the peak interval','Keep sample maxima separate from production metrics'],'peak_velocity',['peak'],'The figure uses our smoothed sample-speed estimates. It does not reproduce SkillCorner’s validated production Peak Velocity. Pros: interpretable capacity measure. Cons: noisy spikes, short exposure and preprocessing dependence.')
    add('Expected goals: shot quality',['Distance and angle form a simple feature baseline','Tracking adds keeper and defender context','Fit and calibrate on many labeled shots'],'xg',['xg'],'Hypothetical shot rays at a real ball location; no xG prediction is invented. Pros: familiar target and interpretable features. Cons: sparse shots, outcome imbalance and contextual bias.')
    add('Expected Threat: location value',['Divide the pitch into states','Combine shooting reward with future movement value','Iterate the transition equation to value continuation'],'xt',['xt','dbxt'],'Actual fitted DataBallPy open-play grid, not trained on this small sample. V(s)=P(shot|s)P(goal|shot,s)+sum P(successful move to s\'|s)V(s\'). Classic location xT does not use defender positions. State the model target and training domain.')
    add('Expected Threat gained',['Look up the value at both endpoints','Completed-action value: V(end) − V(start)','Use tracking context to explain what location-only xT misses'],'xt_gain',['xt','dbxt'],'The arrow is real ball displacement in the selected clip, not an assertion of a single completed pass. Attack direction is normalized and 105 m scaled to the model’s 106 m convention. Pros: simple action valuation. Cons: path-independent, no defender context or causal attribution.',cue='NOTEBOOK · xT lookup and endpoint difference')
    add('Voronoi space control',['Assign every location to its closest player','Aggregate player regions by team','Use as a geometric baseline'],'voronoi',['space'],'Actual frame, grid approximation to a Voronoi partition. Pros: quick and interpretable. Cons: hard boundaries and no movement, ball-flight or uncertainty.')
    add('Gaussian player influence',['Project influence in the player’s movement direction','Let covariance describe directional reach','Inspect the individual surface before aggregating'],'individual_gaussian',['gaussian','movement'],'Real player velocity with an illustrative ellipse. The covariance is not the exact Fernández/Bornn parameterization. Pros: smooth and motion-aware. Cons: hand-set influence scale and simplified movement ability.')
    add('Gaussian team control',['Aggregate individual influence by team','Compare team influence continuously across the pitch','Interpret the result as an influence score'],'gaussian',['gaussian','space'],'Our logistic transformation bounds the team difference; it is not a calibrated possession probability. Pros: contested-space view. Cons: aggregation and covariance assumptions affect the surface.')
    add('Arrival-time control',['Estimate reaction and travel time to each location','Compare the earliest arrival for each team','Test sensitivity to movement assumptions'],'arrival',['movement','spearman'],'Actual frame with a simple 0.7 s projection and 5 m/s travel speed baseline. Pros: interpretable timing. Cons: no ball flight, acceleration optimization or interception-rate integration; not Spearman’s full model.')
    add('Ball-aware pitch control',['Simulate how long the ball takes to reach a target','Estimate player interception and control over that interval','Combine competing control rates'],'physics',['spearman'],'Architecture schematic on actual tracking context, not a computed Spearman surface. Pros: physical link to passing. Cons: uncertain reactions, speed and ball parameters. Separate from the arrival-time teaching baseline.')
    add('Expected pass completion',['Specify a passer and candidate destination','Simulate ball travel and interception opportunities','Evaluate reliability on labeled attempts'],'completion',['das','accessible'],'Actual accessible-space xC inference on hypothetical endpoints at real teammate positions. Pros: interpretable risk. Cons: model calibration, ball speed and offside conventions; candidates are not observed choices.',cue='NOTEBOOK · candidate-pass risk')
    add('Accessible space',['Simulate passes across directions and speeds','Estimate where the attacking team can receive','Integrate accessibility across the pitch'],'accessible',['accessible','das'],'Actual public-model output. Pros: incorporates ball and player movement. Cons: simulation assumptions and resolution; individual access can overlap.')
    add('Dangerous accessible space',['Weight accessible locations by goal danger','Integrate to obtain danger-weighted space','Keep danger-weighted area distinct from scoring probability'],'dangerous',['accessible','das'],'Actual public-model dangerous surface. Pros: links access and useful territory. Cons: danger definition and physical assumptions; DAS units are danger-weighted square metres.')
    add('Changes in dangerous space',['Compare the model on successive real frames','Report AS and DAS on their own scales','Inspect the movements that change available options'],'das_change',['accessible'],'Actual model values on three frames. Pros: connects movement to changing opportunity. Cons: different team possession states and model noise must be checked; before/after changes alone are not causal credit.')
    add('Off-ball run threat',['Evaluate a run even when no pass is made','SkillCorner’s target considers a run being served','Separate run threat from location-based event xT'],'run_threat',['runs','skillcorner'],'Actual supplied xthreat values for off-ball runs. The provider model is not reconstructed. Pros: visible unserved contributions. Cons: counterfactual assumptions, context and selection bias.')
    add('Tracking as a spatial graph',['Represent players as nodes','Choose relationships that define spatial edges','Preserve identities while avoiding arbitrary row-order effects'],'graph',['ussf','tacticai'],'Real radius graph. Pros: models relationships directly. Cons: radius edges miss distant tactical relationships; fully connected and learned connectivity are alternatives.')
    add('Node and edge features',['Nodes: position, velocity, team and possession','Edges: distance, relative position and team relation','Normalize and mask missing features explicitly'],'edge_features',['ussf'],'Actual edge-feature rows. Edge direction controls the sign of relative position. Team IDs should be encoded meaningfully rather than treated as numeric magnitudes.')
    add('Graph neural message passing',['Create messages from players and their relationships','Aggregate neighbour messages with shared functions','Update player representations for a prediction task'],'message',['tacticai','defcon'],'Architecture schematic, not a trained result. Pros: relational inductive bias and shared updates. Cons: oversmoothing, connectivity choices and training requirements. Attention alone is not causal importance.')
    add('Temporal node features',['Add lagged speed, displacement and relative movement','Use rolling history only up to prediction time','Include elapsed time and missing-history masks'],'temporal_features',['ussf','preprocess'],'Actual one-second lag and speed change on a real player. Explicit lag frame checks prevent bridging gaps. Instantaneous velocity adds motion information but is not a substitute for full history.',cue='NOTEBOOK · lagged features and masks')
    add('Dynamic graphs over time',['Recompute spatial edges as players move','Maintain player identities across snapshots','Model changing passing lanes and defensive relationships'],'dynamic_graph',['ussf','pathcrf'],'Actual snapshots and a player trail. A sequence of spatial graphs retains team interactions that change with time; a static aggregate passing network does not.')
    add('Temporal edges between snapshots',['Link each player to their previous observed state','Retain spatial edges within each frame','Direct historical connections toward the prediction time'],'temporal_edges',['pathcrf'],'Schematic topology with real player IDs. The notebook creates actual spatial and temporal edge records. Do not connect across substitutions or tracking gaps without an explicit rule; labels cannot leak future frames.')
    add('Recurrent temporal graph models',['Encode each frame with a spatial GNN','Update a recurrent hidden state as frames arrive','Predict from the accumulated historical state'],'gru',['pathcrf','gentac'],'Architecture schematic rather than a claim about a specific cited model’s GRU implementation. Pros: sequential processing with a compact state. Cons: long-history retention and sequence alignment. No trained inference is shown.')
    add('Temporal convolution on graph history',['Stack frame-level graph embeddings over time','Apply causal filters across historical windows','Control the receptive field with layers and dilation'],'tcn',['gentac'],'Architecture schematic. Pros: parallel computation and explicit receptive field. Cons: window length, dilation and sampling-rate choices. Filters must not access future frames at prediction time.')
    add('Causal temporal attention',['Add time information to historical graph embeddings','Attend to relevant earlier states','Mask future frames and missing observations'],'attention',['gentac'],'Architecture schematic. Pros: flexible history selection and long-range dependencies. Cons: data/computation requirements, masking and leakage; attention weights do not establish causal importance.')
    add('Spatiotemporal message passing',['Connect spatial neighbors within each frame','Connect player identities across observed time','Learn updates over both relationship types'],'spatiotemporal',['pathcrf'],'General architecture schematic, not a reproduction of PathCRF. Pros: joint relational/time structure. Cons: graph size, identity errors and edge construction choices.')
    add('SoccerMap: spatial neural prediction',['Convert tracking into spatial feature channels','Learn field-wide surfaces with convolutional networks','Use distinct heads or models for distinct targets'],'soccermap',['soccermap'],'Architecture schematic. SoccerMap is a convolutional approach, not a GNN. Pros: field-wide outputs. Cons: rasterization and training data requirements; no pretrained inference is claimed.')
    add('Expected possession value',['Specify what outcome and horizon value means','Combine action selection, success and continuation','Include the value of failure and turnovers'],'epv',['epv','defcon'],'Conceptual decomposition: sum over actions P(action|state) times outcome-conditional value, including failure. EPV is a framework/target, not a synonym for GNN. Different EPV definitions must not be mixed.')
    add('Observed passes and supplied EPV',['Inspect value changes on actual pass events','Compare valuable actions with their tracking context','Keep supplied predictions separate from our calculations'],'provider_epv',['skillcorner','epv'],'Actual pass_epv_delta_for fields in SkillCorner dynamic events. This is the provider’s model output; not a reconstructed Fernández or DEFCON prediction. The field name is shown rather than assuming undocumented equivalence.',cue='NOTEBOOK · supplied event-value fields')
    add('DEFCON: defensive contribution',['Use graph-based models for action components','Estimate the opponent’s possession value','Account for defenders’ contribution to reducing danger'],'defcon',['defcon'],'Architecture schematic only. Explain attribution assumptions before interpreting defensive credits. Actual frame is context, not DEFCON inference.')
    add('U.S. Soccer: counterattack graphs',['Build graphs from synchronized SkillCorner and events','Define counterattack success explicitly','Evaluate predictions on held-out sequences'],'counterattack',['ussf'],'Architecture schematic. The published balanced event-frame study uses reaching the penalty area as success; the repository’s additional all-frame dataset has different goal labels. Do not mix those datasets or quote them as equivalent.')
    add('TacticAI: corner-kick modeling',['Predict receiver and shot outcomes','Represent player interactions with graph networks','Suggest alternative positional configurations'],'tacticai',['tacticai'],'Architecture schematic. The input illustration uses real tracking near a supplied corner-reception event; it is not the original TacticAI input or trained inference. Complete task-specific code/weights and licensed data are not released. Model-generated suggestions are not guarantees.')
    add('Trajectory forecasting',['Encode observed player and team history','Generate multiple plausible continuations','Evaluate geometry, tactical coherence and uncertainty'],'forecast',['gentac'],'Architecture schematic; no invented future trajectories are shown as learned output. GenTac is a recent preprint example. Distinguish forecasting and causal intervention.')
    add('Validating tracking models',['Split data by matches or independent sequences','Evaluate calibration and task-specific outcomes','Stress-test missingness, direction and parameters'],'validation',['epv','accessible'],'Schematic split only, not measured performance. Event detection needs timing tolerances; probability models need calibration; tactical labels need a clear taxonomy.')
    for s in slides:
        if s['title']=='Recurrent temporal graph models':s['sources']=['temporal']
        if s['title']=='Temporal convolution on graph history':s['sources']=['tcn']
        if s['title']=='Causal temporal attention':s['sources']=['attention','temporal']
        if s['title']=='Spatiotemporal message passing':s['sources']=['temporal','pathcrf']
    return slides

def extend_notebook(cells):
    def md(s):return nbf.v4.new_markdown_cell(textwrap.dedent(s).strip())
    def code(s):return nbf.v4.new_code_cell(textwrap.dedent(s).strip())
    # Preserve original executable groups, move graph material after the simpler models.
    graph=cells[16:18];base=cells[:16]+cells[18:24]
    xt=[md('''## Expected Threat before relational models
Use the fitted **DataBallPy open-play xT grid**, retained with attribution and its license. Location xT is based on event transitions, not trained from this tracking sample. Normalize attacking direction and map the 105 m pitch to the model's 106 m convention. An endpoint difference on an arbitrary tracked ball segment is not automatically a completed-pass value.'''),code('''from analysis_tools import *
grid=xt_grid()
fig,ax=plt.subplots(figsize=(10,6));pitch(ax)
image=ax.imshow(grid.T,origin='lower',extent=(-52.5,52.5,-34,34),cmap='YlOrRd',alpha=.75,aspect='auto')
fig.colorbar(image,ax=ax,label='DataBallPy open-play xT');ax.set_title('Attacking right • fitted external model');plt.show()
start=wide[wide.frame_id.eq(int(frames[20]))].iloc[0]
end=wide[wide.frame_id.eq(int(frames[80]))].iloc[0]
# Brisbane attacks left in the first half: rotate both axes into attack-right coordinates.
v_start=xt_value(-start.ball_x*106/105,-start.ball_y)
v_end=xt_value(-end.ball_x*106/105,-end.ball_y)
print('Observed ball endpoint difference:',float(v_end-v_start))
''')]
    event=[md('''## Possession and event-detection cues
The nearest-player detector below leaves frames unassigned beyond a 2 m zone. Compare candidates with supplied player-possession labels. It does not implement a validated pass detector: ball motion, height, duels and timing require additional logic.'''),code('''from analysis_tools import nearest_possession,centered_shape,line_clusters
candidates=nearest_possession(motion,wide)
display(candidates.head(12))
window=candidates[candidates.frame_id.between(150,280)]
window.plot(x='frame_id',y='ball_distance',title='Nearest player–ball distance')
plt.axhline(2,color='orange',ls='--');plt.show()
keepers={str(p['id']) for p in meta['players'] if 'goalkeeper' in p['player_role']['name'].lower()}
shape=centered_shape(motion[~motion.player_id.isin(keepers)])
display(line_clusters(shape))
shape.plot.scatter(x='x',y='y',title='Team-centered outfield role locations');plt.show()
''')]
    temporal=[md('''## Temporal graph features and identity edges
Static graphs describe a moment. Add historical lagged features, changing spatial edges and identity links through time to represent change. Keep elapsed-time/gap masks. The code builds actual inputs; it does not train a temporal GNN. A frame GNN followed by a GRU, temporal convolution or causal attention are model choices with different assumptions. These retrospective features use offline symmetric position smoothing; an online predictor needs causal preprocessing or an explicit latency allowance.'''),code('''from analysis_tools import temporal_features,temporal_edges
history=temporal_features(motion,frames)
display(history[['frame_id','player_id','speed_kmh','speed_kmh_lag10','speed_change_1s']].dropna().head())
edges_over_time=temporal_edges(motion,frames[:20])
display(edges_over_time.groupby('edge_type').size().to_frame('edge count'))
display(edges_over_time[edges_over_time.edge_type.eq('temporal')].head())
assert (edges_over_time.loc[edges_over_time.edge_type.eq('temporal'),'target_frame'] > edges_over_time.loc[edges_over_time.edge_type.eq('temporal'),'source_frame']).all()
'''),md('''## Supplied SkillCorner run threat and pass EPV
These are supplied model fields, not predictions from our own EPV or GNN. Run xthreat is distinct from the event-location xT grid above. Interpret the provider's target and field definitions before combining values.'''),code('''sample_events=events[events.frame_start.lt(9000)]
display(sample_events[sample_events.event_type.eq('off_ball_run')][['player_name','event_subtype','frame_start','xthreat']].dropna().head(10))
display(sample_events[sample_events.event_type.eq('player_possession')][['frame_start','end_type','pass_outcome','pass_epv_total','pass_epv_delta_for']].dropna(subset=['pass_epv_total']).head(10))
''')]
    return base[:13]+event+base[13:16]+xt+base[16:]+graph+temporal+cells[24:]
